<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>로그인 결과</title><style>body{font-family:Arial,sans-serif;background:#f7f3ed;display:grid;place-items:center;min-height:100vh}.card{background:white;padding:30px;border-radius:18px;width:min(520px,calc(100% - 40px));box-shadow:0 12px 32px #0001}pre{white-space:pre-wrap;word-break:break-all;background:#f4f4f4;padding:14px;border-radius:8px}.ok{color:#18794e}.bad{color:#c62828}</style></head>
<body><main class="card"><h1>소셜 로그인 결과</h1><p id="status">로그인 토큰을 교환하고 있습니다…</p><pre id="result"></pre><a href="{{ route('test.social-login') }}">로그인 화면으로 돌아가기</a></main><script>
const query=new URLSearchParams(location.search),status=document.querySelector('#status'),result=document.querySelector('#result');
if(query.get('error')){status.textContent=query.get('message')||'로그인 실패';status.className='bad';result.textContent=query.get('error');}else{fetch('/api/auth/social/exchange',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({code:query.get('code')})}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.message||'토큰 교환 실패');status.textContent='로그인 성공';status.className='ok';result.textContent=JSON.stringify(data,null,2);}).catch(error=>{status.textContent='로그인 실패';status.className='bad';result.textContent=error.message;});}
</script></body></html>
